package com.crystaln.vpn.desktop.ui

import com.crystaln.vpn.desktop.net.Binaries

/** Max size of a downloaded/imported config file (sanity limit). */
internal const val MAX_IMPORT_BYTES = 512 * 1024

/** Anchor for classloader lookups (must not be a composable). */
internal object AppVersionHolder

/** App version, generated by Gradle from gradle.properties (appVersion). */
internal val APP_VERSION: String by lazy {
    try {
        val stream = AppVersionHolder::class.java.classLoader
            .getResourceAsStream("crystaln/version.properties")
        val text = stream?.use { String(it.readBytes(), Charsets.UTF_8) }.orEmpty()
        text.lineSequence()
            .firstOrNull { it.startsWith("version=") }
            ?.removePrefix("version=")?.trim()
            ?.takeIf { it.isNotEmpty() } ?: "0.1.0"
    } catch (_: Throwable) {
        "0.1.0"
    }
}

internal fun tcpPing(host: String, port: Int): Long = try {
    val started = System.nanoTime()
    java.net.Socket().use { s ->
        s.connect(java.net.InetSocketAddress(host, port), 5000)
    }
    (System.nanoTime() - started) / 1_000_000
} catch (_: Throwable) {
    -1L
}

internal fun downloadText(url: String): String {
    val conn = (java.net.URL(url).openConnection() as java.net.HttpURLConnection).apply {
        connectTimeout = 10_000
        readTimeout = 10_000
        instanceFollowRedirects = true
    }
    try {
        conn.inputStream.use { input ->
            val bytes = input.readNBytes(MAX_IMPORT_BYTES + 1)
            if (bytes.size > MAX_IMPORT_BYTES) {
                throw java.io.IOException("Файл слишком велик для конфига")
            }
            return String(bytes, Charsets.UTF_8)
        }
    } finally {
        conn.disconnect()
    }
}

/** Short human-readable binaries availability line. */
internal fun binStatus(): String {
    val s = Binaries.status()
    return buildList {
        add("xray " + if (s.xrayReady) "✓" else "✗")
        if (com.crystaln.vpn.desktop.Platform.isWindows) {
            add("tun2socks " + if (s.tun2socksReady) "✓" else "✗")
            add("wintun " + if (s.wintunReady) "✓" else "✗")
            add("amneziawg " + if (s.awgReady) "✓" else "✗")
            add("openvpn " + if (s.openVpnReady) "✓" else "✗")
        } else {
            add("tun2socks " + if (s.tun2socksReady) "✓" else "✗")
            add("amneziawg " + if (s.awgReady) "✓" else "✗")
        }
        add("geosite " + if (s.geositeReady) "✓" else "✗")
    }.joinToString(", ")
}

/**
 * Resolves the desktop system theme: GNOME color-scheme, then KDE color
 * scheme, else light (same idea as Android's isSystemInDarkTheme()).
 */
internal fun systemDark(): Boolean {
    try {
        val out = ProcessBuilder("gsettings", "get", "org.gnome.desktop.interface", "color-scheme")
            .start().inputStream.bufferedReader().use { it.readText() }
        if (out.contains("dark", ignoreCase = true)) return true
        if (out.isNotBlank()) return false
    } catch (_: Throwable) {
    }
    try {
        val out = ProcessBuilder("kreadconfig6", "--group", "General", "--key", "ColorScheme")
            .start().inputStream.bufferedReader().use { it.readText() }
        if (out.contains("dark", ignoreCase = true)) return true
    } catch (_: Throwable) {
    }
    return false
}
